import json
with open('metrics.jsonl') as f:
    lines=[json.loads(l) for l in f if l.strip()]
allk=set()
for l in lines:
    if l['step']>0: allk.update(l['data'].keys())
for k in sorted(allk): print(k)
print()
# val-core series
for l in lines:
    d=l['data']
    vk={k:v for k,v in d.items() if 'val' in k.lower() or 'acc' in k.lower()}
    if vk: print(l['step'], {k: round(v,4) if isinstance(v,float) else v for k,v in vk.items()})
"

